changeSet.sql:
ALTER TABLE clinlims.result_run ADD CONSTRAINT result_run_source_chk CHECK (source IN ('ANALYZER', 'WORKPLAN', 'RESULT_ENTRY'));
ALTER TABLE clinlims.result_run ADD CONSTRAINT result_run_state_chk CHECK (state IN ('OPEN', 'HELD', 'COMPLETE', 'SUPERSEDED'));
CREATE UNIQUE INDEX uq_result_run_analyzer_message ON clinlims.result_run (source_connection_id, source_message_id)
 WHERE source = 'ANALYZER' AND source_message_id IS NOT NULL;
CREATE INDEX idx_result_run_state ON clinlims.result_run (state);
